// samplesDir is generated by Phase 1A's sample harness. The path is
// derived from this test file's own location so the tests work
// regardless of where the repo is checked out (CI workspaces are not
// /home/daal).
var samplesDir = filepath.Join(testRepoRoot(), "specs", "test-vectors", "bundles", "samples")

func testRepoRoot() string {
	_, file, _, _ := runtime.Caller(0)
	// .../core/abi/abi_test.go → repo root.
	return filepath.Clean(filepath.Join(filepath.Dir(file), "..", ".."))
}

func TestEndToEndImportConnectDisconnect(t *testing.T) {
	dir := t.TempDir()
	if err := Init(dir, "warn"); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { Shutdown() })

	if VersionString() == "" {
		t.Fatal("empty version")
	}

	// Import → trust prompt expected.
	verdict, _ := ImportSBP(filepath.Join(samplesDir, "signed-A.sbp"))
	if verdict == "" || !contains(verdict, "VerdictTrustPromptNeeded") && !contains(verdict, `"Kind":1`) {
		// Verdict is JSON of the importer.Verdict struct; Kind=1 means
		// VerdictTrustPromptNeeded.
	}
	// Resolve via fingerprint hex (parse it out of the JSON).
	fp := extractField(verdict, "Fingerprint")
	if fp == "" {
		t.Fatalf("could not parse fingerprint from verdict: %s", verdict)
	}
	if _, err := ResolveTrustPrompt(fp, 0); err != nil {
		t.Fatalf("resolve trust: %v", err)
	}

	// Now connect to the imported route.
	if err := SetRoute("sample-route-1"); err != nil {
		t.Fatalf("set route: %v", err)
	}
	if err := ClearRoute(); err != nil {
		t.Fatalf("clear route: %v", err)
	}

	if err := SetMode("lifeline"); err != nil {
		t.Fatal(err)
	}
	if Mode() != "lifeline" {
		t.Fatal("mode not applied")
	}

	if _, err := ExportDiagnostics(); err != nil {
		t.Fatal(err)
	}
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

// extractField is a tiny no-deps JSON peeker for the test.
func extractField(jsonBlob, name string) string {
	key := `"` + name + `":"`
	i := indexOf(jsonBlob, key)
	if i < 0 {
		return ""
	}
	rest := jsonBlob[i+len(key):]
	end := indexOf(rest, `"`)
	if end < 0 {
		return ""
	}
	return rest[:end]
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

// === Phase 2A-Polish: session boundary across Init/Shutdown cycles ===

// TestSessionBoundaryAcrossInits verifies that two engine_init calls
// bracket a budget-session boundary. After the first Init, the budget
// engine instantiated via SetRouteBudget gets a fresh session
// (epoch=1). After Shutdown + Init, the engine is re-instantiated and
// the per-session counter is zero again.
func TestSessionBoundaryAcrossInits(t *testing.T) {
	dir := t.TempDir()

	// First boot.
	if err := Init(dir, "warn"); err != nil {
		t.Fatalf("init #1: %v", err)
	}
	c := mustCore()
	_ = c.store.UpsertPublisher(routestore.PublisherRow{
		PublisherID:    "pub-x",
		DisplayName:    "X",
		TrustLevel:     "tofu",
		FirstSeen:      "2026-04-26T00:00:00Z",
		LastSeenBundle: "2026-04-26T00:00:00Z",
		KeyStatus:      "active",
	})
	_ = c.store.UpsertRoute(routestore.RouteRow{
		RouteID:         "r-em",
		TransportFamily: "vless-reality",
		Engine:          "sing-box",
		SourceType:      "imported",
		PublisherID:     "pub-x",
		TrustState:      "trusted",
		ScarcityClass:   "normal",
		ExpiresAt:       "2027-01-01T00:00:00Z",
		ImportedAt:      "2026-04-26T00:00:00Z",
	})
	if _, err := SetRouteBudget("r-em", "emergency"); err != nil {
		t.Fatalf("SetRouteBudget #1: %v", err)
	}
	eng1 := ensureBudget()
	if got := eng1.SessionEpoch(); got != 1 {
		t.Fatalf("session epoch after first init = %d, want 1", got)
	}
	// Charge enough to push the session counter forward; pin a known
	// non-zero value so we can detect a leak across the boundary.
	if err := eng1.Add("r-em", 25*budget.MiB); err != nil {
		t.Fatalf("Add #1: %v", err)
	}

	// Clean shutdown.
	if err := Shutdown(); err != nil {
		t.Fatalf("shutdown: %v", err)
	}

	// Second boot — same dir.
	if err := Init(dir, "warn"); err != nil {
		t.Fatalf("init #2: %v", err)
	}
	t.Cleanup(func() { Shutdown() })

	eng2 := ensureBudget()
	if eng2 == eng1 {
		t.Fatalf("ensureBudget returned the same engine across Shutdown/Init — singleton not reset")
	}
	if got := eng2.SessionEpoch(); got != 1 {
		t.Fatalf("session epoch on fresh engine after second init = %d, want 1", got)
	}
	// The fresh engine must report zero session_consumed for r-em
	// regardless of the persisted hourly counter (which is per-route
	// per-hour and unrelated to the session axis).
	for _, snap := range eng2.Snapshot() {
		if snap.RouteID == "r-em" && snap.SessionConsumed != 0 {
			t.Errorf("session counter leaked across Shutdown/Init: %+v", snap)
		}
	}
}

// === Phase 2B: mode wiring + posture + diagnostics widening ===

// TestSetModeWiresToBudgetEngine asserts that SetMode("lifeline")
// makes the budget engine's Snapshot return *effective* (0.33×) caps.
func TestSetModeWiresToBudgetEngine(t *testing.T) {
	dir := t.TempDir()
	if err := Init(dir, "warn"); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { Shutdown() })

	c := mustCore()
	_ = c.store.UpsertPublisher(routestore.PublisherRow{
		PublisherID:    "pub-x",
		DisplayName:    "X",
		TrustLevel:     "tofu",
		FirstSeen:      "2026-04-26T00:00:00Z",
		LastSeenBundle: "2026-04-26T00:00:00Z",
		KeyStatus:      "active",
	})
	_ = c.store.UpsertRoute(routestore.RouteRow{
		RouteID:         "r-em",
		TransportFamily: "vless-reality",
		Engine:          "sing-box",
		SourceType:      "imported",
		PublisherID:     "pub-x",
		TrustState:      "trusted",
		ScarcityClass:   "normal",
		ExpiresAt:       "2027-01-01T00:00:00Z",
		ImportedAt:      "2026-04-26T00:00:00Z",
	})
	if _, err := SetRouteBudget("r-em", "emergency"); err != nil {
		t.Fatalf("SetRouteBudget: %v", err)
	}
	eng := ensureBudget()
	// Default mode (normal) → hourly cap is the raw 50 MiB.
	for _, snap := range eng.Snapshot() {
		if snap.RouteID == "r-em" && snap.HourlyCap != 50*budget.MiB {
			t.Errorf("normal mode: hourly_cap = %d, want 50 MiB", snap.HourlyCap)
		}
	}

	if err := SetMode("lifeline"); err != nil {
		t.Fatalf("SetMode lifeline: %v", err)
	}
	wantHourly := uint64(float64(50*budget.MiB) * 0.33)
	for _, snap := range eng.Snapshot() {
		if snap.RouteID == "r-em" && snap.HourlyCap != wantHourly {
			t.Errorf("lifeline mode: hourly_cap = %d, want %d", snap.HourlyCap, wantHourly)
		}
	}
}

// TestSetModeFlipsToPostureLifelineWhenActive asserts that lifeline
// mode flips ImportedActive → Lifeline. Also asserts switching back
// to normal restores ImportedActive.
func TestSetModeFlipsToPostureLifelineWhenActive(t *testing.T) {
	dir := t.TempDir()
	if err := Init(dir, "warn"); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { Shutdown() })

	c := mustCore()
	// Drive posture into ImportedActive (legal: NoRoute → ImportedActive).
	if err := c.pm.SetPosture(pathmanager.EventImportedSelected, pathmanager.PostureImportedActive); err != nil {
		t.Fatalf("seed posture: %v", err)
	}
	if err := SetMode("lifeline"); err != nil {
		t.Fatal(err)
	}
	if got := c.pm.Posture(); got != pathmanager.PostureLifeline {
		t.Errorf("posture after lifeline mode = %q, want %q", got, pathmanager.PostureLifeline)
	}
	if err := SetMode("normal"); err != nil {
		t.Fatal(err)
	}
	if got := c.pm.Posture(); got != pathmanager.PostureImportedActive {
		t.Errorf("posture after normal mode = %q, want %q", got, pathmanager.PostureImportedActive)
	}
}

// TestSetModeRejectsLifelineStrict asserts that the 2D mode is NOT
// TestSetModeAcceptsLifelineStrict asserts the 2D widening: the
// engine_set_mode boundary now accepts `lifeline-strict`. The strict
// variant flips the posture into PostureLifeline (same as lifeline)
// and threads into the budget engine via SetMode (driving the same
// 0.33× multiplier).
func TestSetModeAcceptsLifelineStrict(t *testing.T) {
	dir := t.TempDir()
	if err := Init(dir, "warn"); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { Shutdown() })

	c := mustCore()
	if err := c.pm.SetPosture(pathmanager.EventImportedSelected, pathmanager.PostureImportedActive); err != nil {
		t.Fatalf("seed posture: %v", err)
	}

	if err := SetMode("lifeline-strict"); err != nil {
		t.Fatalf("expected SetMode(lifeline-strict) to be accepted at 2D, got: %v", err)
	}
	if got := Mode(); got != "lifeline-strict" {
		t.Fatalf("Mode() = %q, want lifeline-strict", got)
	}
	if c.pm.Posture() != pathmanager.PostureLifeline {
		t.Fatalf("posture = %v, want PostureLifeline", c.pm.Posture())
	}
}

// TestSetModeLifelineStrictDoesNotResetSession asserts the 2A-Polish
// rule continues to hold for the new mode: mode change MUST NOT bump
// the budget session epoch.
func TestSetModeLifelineStrictDoesNotResetSession(t *testing.T) {
	dir := t.TempDir()
	if err := Init(dir, "warn"); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { Shutdown() })

	// Touch the budget engine to force instantiation + capture epoch.
	if _, err := SetRouteBudget("r-1", "normal"); err != nil {
		t.Fatal(err)
	}
	eng := budgetEngineIfPresent()
	if eng == nil {
		t.Fatal("budget engine not instantiated after SetRouteBudget")
	}
	before := eng.SessionEpoch()

	if err := SetMode("lifeline-strict"); err != nil {
		t.Fatal(err)
	}
	if after := eng.SessionEpoch(); after != before {
		t.Fatalf("session epoch changed across SetMode(lifeline-strict): %d → %d", before, after)
	}
}

// TestExportDiagnosticsCarriesPostureAndRouteHealth asserts the new
// 2B diagnostics fields are present.
func TestExportDiagnosticsCarriesPostureAndRouteHealth(t *testing.T) {
	dir := t.TempDir()
	if err := Init(dir, "warn"); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { Shutdown() })

	c := mustCore()
	c.pm.Failed("r-broken", "vless-reality", diagnostics.TCPReset)

	body, err := ExportDiagnostics()
	if err != nil {
		t.Fatal(err)
	}
	var blob struct {
		Posture         string                   `json:"posture"`
		RouteHealth     []map[string]interface{} `json:"route_health"`
		SkippedFamilies []map[string]interface{} `json:"skipped_families"`
	}
	if err := json.Unmarshal([]byte(body), &blob); err != nil {
		t.Fatalf("decode diagnostics: %v\n%s", err, body)
	}
	if blob.Posture != "NoRoute" {
		t.Errorf("posture = %q, want NoRoute (default)", blob.Posture)
	}
	// route_health[] must include r-broken with cooldown_reason tcp_reset.
	found := false
	for _, row := range blob.RouteHealth {
		if row["route_id"] == "r-broken" {
			found = true
			if row["cooldown_reason"] != "tcp_reset" {
				t.Errorf("cooldown_reason = %v, want tcp_reset", row["cooldown_reason"])
			}
			if row["in_cooldown"] != true {
				t.Errorf("in_cooldown = %v, want true", row["in_cooldown"])
			}
		}
	}
	if !found {
		t.Errorf("r-broken not in route_health[]: %+v", blob.RouteHealth)
	}
}

// TestModeChangeDoesNotResetSession asserts that engine_set_mode does
// NOT bump the session epoch. Mode change must not launder the
// per-session counter — that would let a user reset their cap by
// flipping modes.
func TestModeChangeDoesNotResetSession(t *testing.T) {
	dir := t.TempDir()
	if err := Init(dir, "warn"); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { Shutdown() })

	c := mustCore()
	_ = c.store.UpsertPublisher(routestore.PublisherRow{
		PublisherID:    "pub-x",
		DisplayName:    "X",
		TrustLevel:     "tofu",
		FirstSeen:      "2026-04-26T00:00:00Z",
		LastSeenBundle: "2026-04-26T00:00:00Z",
		KeyStatus:      "active",
	})
	_ = c.store.UpsertRoute(routestore.RouteRow{
		RouteID:         "r-em",
		TransportFamily: "vless-reality",
		Engine:          "sing-box",
		SourceType:      "imported",
		PublisherID:     "pub-x",
		TrustState:      "trusted",
		ScarcityClass:   "normal",
		ExpiresAt:       "2027-01-01T00:00:00Z",
		ImportedAt:      "2026-04-26T00:00:00Z",
	})
	if _, err := SetRouteBudget("r-em", "emergency"); err != nil {
		t.Fatal(err)
	}
	eng := ensureBudget()
	beforeEpoch := eng.SessionEpoch()
	if err := SetMode("lifeline"); err != nil {
		t.Fatal(err)
	}
	if err := SetMode("normal"); err != nil {
		t.Fatal(err)
	}
	if err := SetMode("bulk"); err != nil {
		t.Fatal(err)
	}
	if got := eng.SessionEpoch(); got != beforeEpoch {
		t.Errorf("session epoch advanced on mode change: before=%d after=%d", beforeEpoch, got)
	}
}

// === Gap 5: posture FSM tightening — wire dead producers ===

// seedExperimentalRoute inserts a publisher + a route on an
// experimental-maturity family (webtunnel) plus its sing-box outbound
// profile blob so SetRoute can drive Start through the stub.
func seedExperimentalRoute(t *testing.T, c *Core, routeID string) {
	t.Helper()
	if err := c.store.UpsertPublisher(routestore.PublisherRow{
		PublisherID:    "pub-exp",
		DisplayName:    "Exp",
		TrustLevel:     "tofu",
		FirstSeen:      "2026-05-29T00:00:00Z",
		LastSeenBundle: "2026-05-29T00:00:00Z",
		KeyStatus:      "active",
	}); err != nil {
		t.Fatalf("UpsertPublisher: %v", err)
	}
	if err := c.store.UpsertRoute(routestore.RouteRow{
		RouteID:         routeID,
		TransportFamily: "webtunnel",
		Engine:          "sing-box",
		SourceType:      "imported",
		PublisherID:     "pub-exp",
		TrustState:      "trusted",
		ScarcityClass:   "normal",
		ExpiresAt:       "2027-01-01T00:00:00Z",
		ImportedAt:      "2026-05-29T00:00:00Z",
	}); err != nil {
		t.Fatalf("UpsertRoute: %v", err)
	}
	// Minimal sing-box outbound JSON; BuildSingBoxConfig only checks
	// JSON validity and the absence of a tag, both of which this
	// satisfies.
	if err := c.store.PutSecret("route:"+routeID,
		[]byte(`{"type":"webtunnel","server":"example.invalid","server_port":443}`)); err != nil {
		t.Fatalf("PutSecret: %v", err)
	}
}

