// TestGap5_SetRouteExperimentalAdvancesToPostureExperimental — Gap 5:
// SetRoute on an experimental-family route from PostureNoRoute must
// advance the posture to PostureExperimental, not PostureImportedActive.
// This relies on the new {NoRoute, experimental_selected, Experimental}
// table edge.
func TestGap5_SetRouteExperimentalAdvancesToPostureExperimental(t *testing.T) {
	dir := t.TempDir()
	if err := Init(dir, "warn"); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { Shutdown() })

	c := mustCore()
	seedExperimentalRoute(t, c, "r-exp")

	if got := c.pm.Posture(); got != pathmanager.PostureNoRoute {
		t.Fatalf("seed posture = %s, want %s", got, pathmanager.PostureNoRoute)
	}
	if err := SetRoute("r-exp"); err != nil {
		t.Fatalf("SetRoute: %v", err)
	}
	if got := c.pm.Posture(); got != pathmanager.PostureExperimental {
		t.Fatalf("posture after SetRoute(experimental) = %s, want %s",
			got, pathmanager.PostureExperimental)
	}
}

